def factorial(n: int) -> int:
    """Calcula el factorial de n. Fractal: cada n! contiene el patrón de (n-1)!"""
    if n < 0:
        raise ValueError('factorial no definido para negativos')
    if n <= 1:
        return 1
    return n * factorial(n - 1)

