  SPAWN(teoria): Un embedding mapea índices discretos a vectores densos en R^d
  SPAWN(implementacion):
    import numpy as np

    class FractalEmbedding:
        """EVOLVE: capa de embedding fractal — cada token es un punto en espacio vectorial"""
        def __init__(self, vocab_size: int, embed_dim: int, seed: int = 1979):
            rng = np.random.default_rng(seed)
            # Inicialización de Kaiming — escala óptima para distribuciones de entrada
            scale = np.sqrt(2.0 / embed_dim)
            self.W = rng.normal(0, scale, (vocab_size, embed_dim)).astype(np.float32)
            self.vocab_size = vocab_size
            self.embed_dim = embed_dim

        def forward(self, indices: np.ndarray) -> np.ndarray:
            """LINK(indice, vector): mapeo directo por lookup"""
            IF(np.any(indices >= self.vocab_size),
               raise ValueError(f'Índice fuera de rango: max={self.vocab_size-1}'))
            return self.W[indices]  # shape: (batch, seq_len, embed_dim)

        def backward(self, indices: np.ndarray, grad_output: np.ndarray, lr: float = 1e-3):
            """EVOLVE: actualiza embeddings por gradiente"""
            np.add.at(self.W, indices, -lr * grad_output)

        def similitud_coseno(self, v1: np.ndarray, v2: np.ndarray) -> float:
            """LINK: mide distancia semántica entre dos embeddings"""
            return np.dot(v1, v2) / (np.linalg.norm(v1) * np.linalg.norm(v2) + 1e-8)

        def tokens_cercanos(self, vector: np.ndarray, top_k: int = 5) -> list:
            """SPAWN: encuentra los k tokens más similares"""
            sims = self.W @ vector / (np.linalg.norm(self.W, axis=1) * np.linalg.norm(vector) + 1e-8)
            return np.argsort(sims)[-top_k:][::-1].tolist()

