    from typing import Any, Callable, Iterable
    import inspect

    # ── SUM(A, B) ──────────────────────────────────────────────────────────
    def SUM(*args: Any) -> Any:
        """Integra conceptos preservando ambos. Union, no replacement."""
        IF(all(isinstance(a, dict) for a in args)):
            resultado = {}
            for d in args: resultado.update(d)
            return resultado
        ELIF(all(isinstance(a, list) for a in args)):
            return [item for a in args for item in a]
        ELIF(all(isinstance(a, str) for a in args)):
            return ' '.join(args)
        ELIF(all(isinstance(a, (int, float)) for a in args)):
            return sum(args)
        ELSE:
            return args[0] if len(args) == 1 else args

    # ── IF(cond, A, B) ─────────────────────────────────────────────────────
    def IF(cond: Any, entonces: Any, sino: Any = None) -> Any:
        """Bifurca el flujo según condición. Versión funcional del if."""
        resultado = entonces if cond else sino
        IF(callable(resultado)):
            return resultado()
        return resultado

    # ── LOOP(n, op) ────────────────────────────────────────────────────────
    def LOOP(n: int | Iterable, op: Callable, estado_inicial: Any = None) -> Any:
        """Itera refinando. Cada iteración puede modificar el estado."""
        IF(isinstance(n, int)):
            estado = estado_inicial
            for i in range(n):
                estado = op(i, estado) if op.__code__.co_argcount >= 2 else op(i)
            return estado
        ELSE:
            return [op(item) for item in n]

    # ── SPAWN(entidad, ctx) ────────────────────────────────────────────────
    def SPAWN(nombre: str, funcion: Callable = None, contexto: dict = None) -> dict:
        """Crea una perspectiva especializada. Sub-agente virtual."""
        ctx = contexto or {}
        IF(funcion is not None):
            resultado = funcion(**ctx) if ctx else funcion()
            return {'nombre': nombre, 'resultado': resultado, 'contexto': ctx}
        return {'nombre': nombre, 'contexto': ctx, 'activo': True}

    # ── FOLD(lista, fn) ────────────────────────────────────────────────────
    def FOLD(items: list, fn: Callable = None, inicial: Any = None) -> Any:
        """Reduce múltiples ideas a una síntesis."""
        IF(fn is None):
            return items[0] if len(items) == 1 else items
        from functools import reduce
        IF(inicial is not None):
            return reduce(fn, items, inicial)
        return reduce(fn, items)

    # ── LINK(nodo_A, nodo_B) ───────────────────────────────────────────────
    def LINK(a: Any, b: Any, peso: float = 1.0, bidireccional: bool = True) -> dict:
        """Conecta conceptos distantes. Crea relación semántica."""
        enlace = {'origen': a, 'destino': b, 'peso': peso}
        IF(bidireccional):
            enlace['inverso'] = {'origen': b, 'destino': a, 'peso': peso}
        return enlace

    # ── EVOLVE(code, err, fix) ─────────────────────────────────────────────
    def EVOLVE(objeto: Any, error: Any = None, fix: Callable = None) -> Any:
        """Aprende de errores. Auto-corrección funcional."""
        IF(error is None and fix is None):
            return objeto  # sin cambios
        IF(fix is not None and callable(fix)):
            try:
                return fix(objeto)
            except Exception as e:
                return EVOLVE(objeto, e, None)  # LOOP de evolución si el fix falla
        # Si hay error pero no fix, retornar objeto con marca de error
        return {'objeto_original': objeto, 'error_detectado': str(error), 'requiere_fix': True}

    # ── Composición fractal ────────────────────────────────────────────────
    def fractal_compose(*operaciones: Callable) -> Callable:
        """FOLD(operaciones, componer): crea pipeline de operaciones fractales"""
        return FOLD(list(operaciones), lambda f, g: lambda x: g(f(x)))

    # Ejemplo de uso:
    pipeline = fractal_compose(
        lambda x: SPAWN('analisis', lambda: x.split()),
        lambda s: FOLD(s['resultado'], lambda a,b: SUM(a, b)),
        lambda r: EVOLVE(r, fix=lambda x: x.strip() if isinstance(x, str) else str(x))
    )

